// Фикстура проверки подсистемы TileMap (тест tests/agent/highlevel_tilemap_test.py).
//
// Здесь намеренно нет текстурной зависимости: карта строится из ASCII, а логика
// (индексация, автотайл, коллизии) работает и без загруженного тайлсета.
$.ready(() => {
    $.world.gravity(0, 1200).color('#101820').bounds(0, 0, 1280, 720);

    // Основной уровень: '#1' — непроходимый тайл, '.' — пусто.
    $.tilemap.fromASCII([
        '1111111111',
        '1........1',
        '1..111...1',
        '1........1',
        '1111111111',
    ], { '1': 1, '.': 0 }, { id: 'level', src: 'assets/atlas.png', tile: 32, solid: true })
        .at(0, 0);

    // Второй слой поверх: depth рисуется позже, solid выключен.
    $('<tilemap>', {
        id: 'deco',
        src: 'assets/atlas.png',
        tile: 32,
        cols: 4,
        layers: [
            { data: ['....', '.11.', '.11.', '....'], solid: false, depth: 10, tile: 32 },
        ],
    }).at(0, 0);
});
